<script lang="ts">
 import {onMount} from 'svelte';
 import * as api from '../../bindings';
 import ErrorNotice from '../../ErrorNotice.svelte';
 import type {CaseOperations} from '../operations/controller.svelte';
 let {artifact,generation,page,operations,onopen,onface}:{artifact:string;generation:number;page:number;operations:CaseOperations;onopen?:(id:string,page?:number)=>void;onface?:(face:api.FaceView)=>void}=$props();
 const initialRecipe=():api.ImageRecipe=>({version:1,crop:null,quarter_turns:0,mirror_horizontal:false,mirror_vertical:false,brightness:0,contrast:0,red:0,green:0,blue:0,obscure:[]});
 let recipe=$state(initialRecipe()),crop=$state(false),rect=$state<api.ImageRect>({x:0,y:0,width:1000,height:1000});
 let faces=$state<api.FaceView[]>([]),face=$state(''),obscure=$state(false),faceTotal=$state(0);
 let lineage=$state<Record<string,unknown>|null>(null);
 let derived=$state(''),prepared=$state<api.MediaView|null>(null),info=$state<Record<string,unknown>|null>(null);
 let error=$state<api.CommandError|null>(null),busy=$state(false),results=$state<api.ImageSearchPage|null>(null),offset=$state(0),mode=$state('duplicates'),distance=$state(8),budget=$state(5000),sort=$state('best'),domain=$state(''),from=$state(''),through=$state(''),title=$state(''),minimum=$state<number|undefined>(),maximum=$state<number|undefined>();
 let usePrepared=$state(true),url=$state(''),consent=$state(false),dropped=$state<api.ResearchDrop|null>(null),notice=$state('');let active=true,serial=0;
 onMount(()=>{let stop:(()=>void)|undefined;void api.researchDropListen(event=>{if(active&&event.generation===generation)dropped=event;}).then(unlisten=>{if(active)stop=unlisten;else unlisten();}).catch(()=>{});return()=>{active=false;serial++;stop?.();};});
 $effect(()=>{artifact;page;generation;recipe=initialRecipe();crop=false;face='';obscure=false;derived='';prepared=null;results=null;info=null;faces=[];faceTotal=0;busy=false;serial++;});
 $effect(()=>{url;consent=false;});
 $effect(()=>{const id=artifact,g=generation;let current=true;lineage=null;void api.imageQueryInfo(g,id).then(value=>{if(current)lineage=value;}).catch(raw=>{if(current)error=api.asCommandError(raw);});return()=>{current=false;};});
 $effect(()=>{const result=operations.result;if(result?.derived===true&&result.source_artifact_id===artifact&&typeof result.artifact_id==='string'){derived=result.artifact_id;void loadPrepared(derived);}});
 async function loadPrepared(id:string){const n=++serial;busy=false;try{const [preview,provenance]=await Promise.all([api.mediaRead(generation,id),api.imageQueryInfo(generation,id)]);if(active&&n===serial){prepared=preview;info=provenance;}}catch(raw){if(active)error=api.asCommandError(raw);}}
 async function loadFaces(){const id=artifact,current=page,g= generation;try{const p=await api.facePage(g,id,0,false,current);if(active&&id===artifact&&current===page&&g===generation){faces=p.faces;faceTotal=p.total;}}catch(raw){if(active&&id===artifact&&current===page&&g===generation)error=api.asCommandError(raw);}}
 function cropFace(){const f=faces.find(f=>f.id===face);if(!f||!f.image_size[0]||!f.image_size[1])return;const [x,y,w,h]=f.bbox;const left=Math.max(0,Math.min(999,Math.floor(x/f.image_size[0]*1000))),top=Math.max(0,Math.min(999,Math.floor(y/f.image_size[1]*1000)));const right=Math.max(left+1,Math.min(1000,Math.ceil((x+w)/f.image_size[0]*1000))),bottom=Math.max(top+1,Math.min(1000,Math.ceil((y+h)/f.image_size[1]*1000)));rect={x:left,y:top,width:right-left,height:bottom-top};crop=true;}
 async function prepare(){error=null;await operations.run('image_prepare',{version:1,artifact_id:artifact,page,recipe:{...$state.snapshot(recipe),crop:crop?{...rect}:null},selected_face_id:face||null,obscure_other_faces:obscure} satisfies api.ImagePrepareRequest);}
 async function search(next=0){const n=++serial;busy=true;error=null;try{const value=await api.imageQuerySearch(generation,{version:1,artifact_id:usePrepared&&derived?derived:artifact,page:usePrepared&&derived?0:page,mode,max_distance:distance,scan_limit:budget,offset:next,sort,domain,date_from:from,date_to:through,title,min_bytes:minimum??null,max_bytes:maximum??null});if(active&&n===serial){results=value;offset=next;}}catch(raw){if(active&&n===serial)error=api.asCommandError(raw);}finally{if(active&&n===serial)busy=false;}}
 async function paste(event:ClipboardEvent){const files=[...(event.clipboardData?.files??[])];if(!files.length)return;event.preventDefault();if(files.length!==1||files[0].size>10*1024*1024||!['image/png','image/jpeg','image/webp'].includes(files[0].type)){notice='Paste one PNG/JPEG/WEBP image up to 10 MiB.';return;}const file=files[0];const bytes=new Uint8Array(await file.arrayBuffer());let encoded='';for(let i=0;i<bytes.length;i+=32768)encoded+=String.fromCharCode(...bytes.subarray(i,i+32768));if(!active)return;await operations.run('image_clipboard_import',{version:1,media_type:file.type,base64:btoa(encoded)});}
 async function collect(){if(!consent||!url||!operations.online)return;await operations.run('collect',{url});consent=false;}
 async function copyId(){if(!derived)return;try{await navigator.clipboard.writeText(derived);notice='Prepared query artifact ID copied.';}catch{notice=`Select and copy this ID: ${derived}`;}}
</script>
<section class="image-research" aria-label="Local image research"><h3>Image preparation and local search</h3><p>Work with this case's encrypted evidence. Preparing a query preserves the original and records the transformation. Nothing is uploaded by these local actions.</p>
 {#if error}<ErrorNotice {error}/>{/if}{#if notice}<p role="status">{notice}</p>{/if}
 {#if lineage}<details class="saved-lineage"><summary>This image's preparation lineage</summary><p>This PNG is derived evidence. Inspect its source and saved recipe before drawing conclusions.</p><pre>{JSON.stringify(lineage,null,2)}</pre>{#if typeof lineage.source_artifact_id==='string'}<button type="button" onclick={()=>onopen?.(String(lineage?.source_artifact_id),typeof lineage?.page==='number'?lineage.page:0)}>Inspect preparation source</button>{/if}</details>{/if}
 <details class="image-editor"><summary>Prepare a query image</summary><p>Crop coordinates use 0–1000 of the orientation-corrected source width/height. For PDFs they address the selected rendered page. Obscuring covers only detected/chosen regions; inspect the output.</p>
 <label class="check"><input type="checkbox" bind:checked={crop}/>Crop source region</label>{#if crop}<div class="controls">{#each ['x','y','width','height'] as key}<label>Crop {key}<input type="number" min={key==='width'||key==='height'?1:0} max="1000" bind:value={rect[key as keyof api.ImageRect]}/></label>{/each}</div>{/if}
 <div class="controls"><label>Rotation<select bind:value={recipe.quarter_turns}><option value={0}>0°</option><option value={1}>90° clockwise</option><option value={2}>180°</option><option value={3}>270° clockwise</option></select></label><label class="check"><input type="checkbox" bind:checked={recipe.mirror_horizontal}/>Mirror horizontally</label><label class="check"><input type="checkbox" bind:checked={recipe.mirror_vertical}/>Mirror vertically</label>{#each ['brightness','contrast','red','green','blue'] as key}<label>{key}<input type="number" min="-100" max="100" bind:value={recipe[key as 'brightness'|'contrast'|'red'|'green'|'blue']}/></label>{/each}</div>
 <button type="button" disabled={operations.busy} onclick={loadFaces}>Load detected faces on this page</button>{#if faceTotal}<label>Selected face<select bind:value={face}><option value="">No face selected</option>{#each faces as f}<option value={f.id}>{f.entity_name??'Unidentified face'} · {f.id}</option>{/each}</select></label><p>{faces.length} of {faceTotal} current detections shown. Use the existing face workspace for more detections and review.</p><div class="actions"><button type="button" disabled={!face} onclick={cropFace}>Crop to selected face</button><button type="button" disabled={!face} onclick={()=>{const f=faces.find(f=>f.id===face);if(f)onface?.(f);}}>Compare selected face locally</button></div><label class="check"><input type="checkbox" bind:checked={obscure} disabled={!face}/>Obscure other detected faces with opaque regions</label>{/if}
 <div class="actions"><button type="button" disabled={operations.busy} onclick={prepare}>Save prepared query locally</button><button type="button" disabled={operations.busy} onclick={()=>{recipe=initialRecipe();rect={x:0,y:0,width:1000,height:1000};crop=false;face='';obscure=false;}}>Reset image recipe</button></div>
 </details>
 {#if derived}<section aria-label="Prepared query image"><h4>Prepared query</h4><p>Saved recipe only; further edits take effect after saving again. Derived artifact: <code>{derived}</code></p>{#if prepared}<img src={`data:image/png;base64,${prepared.preview_png}`} alt="Prepared local query; inspect crop, colors and obscured regions"/>{/if}<div class="actions"><button type="button" onclick={()=>onopen?.(derived)}>Inspect derived evidence</button><button type="button" onclick={copyId}>Copy prepared query ID</button></div><details><summary>Transformation provenance</summary><pre>{JSON.stringify(info,null,2)}</pre></details></section>{/if}
 <details class="image-input"><summary>Import another query image</summary><p>Choose a local file, drop one file into this window, or focus the paste button and paste image bytes. These inputs preserve their own provenance and do not infer an original web URL.</p><div class="actions"><button type="button" disabled={operations.busy} onclick={()=>operations.importFile()}>Import image evidence</button><button type="button" disabled={operations.busy} onpaste={paste}>Focus here and paste an image</button></div>{#if dropped}<p>Dropped file: {dropped.name}</p><button type="button" disabled={operations.busy} onclick={()=>{if(dropped){void operations.run('import',{selection:dropped.selection});dropped=null;}}}>Import dropped image as Evidence</button>{/if}{#if operations.result?.artifact_id&&operations.result?.derived!==true}<button type="button" onclick={()=>onopen?.(String(operations.result?.artifact_id))}>Inspect latest imported or collected evidence</button>{/if}
 <details><summary>Collect an image URL through the broker</summary><p>External collection is separate from local search. The destination sees your IP and requested URL. The bounded broker enforces offline mode, public-address checks and redirect policy. Returned content may be an HTML/error page; inspect its captured type.</p><label>Public image URL<input bind:value={url} type="url" maxlength="8192"/></label><label class="check"><input type="checkbox" bind:checked={consent}/>Collect this explicit URL as case evidence.</label><button type="button" disabled={operations.busy||!operations.online||!url||!consent} onclick={collect}>Collect reviewed image URL</button></details></details>
 <section aria-label="Offline duplicate search"><h4>Search this case</h4><p>Duplicates searches exact file bytes and stored perceptual fingerprints. People uses the existing face workspace. Similar, Related and visually similar Places need a separately validated visual model and are unavailable here.</p><div class="controls"><label>Search category<select bind:value={mode}><option value="duplicates">Duplicates · exact and perceptual candidates</option><option value="exact">Exact captured file bytes only</option><option disabled>Similar · visual model unavailable</option><option disabled>Related · visual model unavailable</option><option disabled>Places · visual model unavailable</option></select></label><label>Candidate scan budget<select bind:value={budget}><option value={500}>500 indexed records</option><option value={5000}>5,000 indexed records</option><option value={20000}>20,000 indexed records</option></select></label><label>Maximum pHash bit distance<input type="number" min="0" max="16" bind:value={distance}/></label><label>Sort candidates<select bind:value={sort}>{#each ['best','worst','newest','oldest','diverse'] as value}<option>{value}</option>{/each}</select></label></div>
 {#if derived}<label class="check"><input type="checkbox" bind:checked={usePrepared}/>Search using the saved prepared image</label>{/if}
 <details><summary>Filter available source metadata</summary><div class="controls"><label>Exact source domain<input bind:value={domain} maxlength="253"/></label><label>Known page title contains<input bind:value={title} maxlength="200"/></label><label>Indexed from<input type="date" bind:value={from}/></label><label>Indexed through<input type="date" bind:value={through}/></label><label>Minimum source bytes<input type="number" min="0" bind:value={minimum}/></label><label>Maximum source bytes<input type="number" min="0" bind:value={maximum}/></label></div><p>Missing titles/domains cannot match their filters. Publication date and language are unknown unless separately established; index dates do not substitute for publication dates.</p></details>
 <button type="button" disabled={busy||operations.busy} onclick={()=>search()}>{busy?'Searching local fingerprints…':'Search duplicates locally'}</button>
 {#if results}<p role="status">{results.total} matches within {results.scanned} scanned records · {results.external_requests} external requests. {results.scan_truncated?'Scan budget reached; additional candidates may exist.':'Scanned indexed records exhausted.'}</p><p>{results.coverage}</p><details><summary>Grouped sources in this scan</summary>{#each Object.entries(results.groups) as [name,count]}<p>{name}: {count}</p>{/each}</details><div class="candidates">{#each results.rows as row}<article><strong>{row.signal}</strong><p>{row.title??row.source_url??row.artifact_id} · page {row.page+1}</p><p>{row.media_type} · {row.byte_length} bytes · {row.domain??'Domain unknown'}{#if row.distance!==null} · bit distance {row.distance}{/if}</p><p>Indexed {row.indexed_utc} · publication/language unknown</p><button type="button" onclick={()=>onopen?.(row.artifact_id,row.page)}>Inspect candidate source</button></article>{/each}</div>{#if !results.total}<p>No matches in this bounded local scope. This does not establish absence elsewhere.</p>{/if}<div class="actions"><button type="button" disabled={busy||!offset} onclick={()=>search(Math.max(0,offset-50))}>Previous image candidates</button><span>{results.total?offset+1:0}–{Math.min(offset+50,results.total)} of {results.total}</span><button type="button" disabled={busy||offset+50>=results.total} onclick={()=>search(offset+50)}>Next image candidates</button></div>{/if}
 </section><p>EXIF fields remain in the source's native observations. C2PA verification and AI/deepfake detection are not implemented in this slice; no authenticity verdict is inferred from missing metadata.</p>
</section>
<style>
 .image-research{margin-block:24px;padding-block:16px;border-top:1px solid var(--border)}details{margin-block:16px}summary{cursor:pointer}p{max-width:75ch;color:var(--foreground-secondary);overflow-wrap:anywhere}.controls{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px;margin-block:12px}label{display:grid;gap:6px;min-width:0}.check{display:flex;align-items:center;gap:8px;margin-block:12px}.check input{width:auto}.actions{display:flex;flex-wrap:wrap;gap:10px;margin-block:12px}input,select{min-width:0;width:100%}img{display:block;max-width:100%;max-height:500px;object-fit:contain}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:350px;overflow:auto}article{padding-block:12px;border-bottom:1px solid var(--border)}code{overflow-wrap:anywhere}
</style>
